from datetime import datetime, timedelta
from flask import jsonify
from flask_login import current_user
from sqlalchemy import event

from app.config import LB_ALLTIME_KEY, LB_WEEKLY_KEY
from app.extensions import db, redis_client
from app.models import Activity, DailyQuest, Friendship, User, UserQuestProgress, WeeklyResetLog, WeeklyWinner
from app.timeutil import app_today


def _lb_score(xp, streak):
    """XP'yi 1e5 ile çarpıp streak'i ekleyerek kompozit sıralama skoru üret."""
    return (xp or 0) * 100000 + min(streak or 0, 99999)


def lb_sync_user(user):
    """Tek kullanıcının skorunu iki sete yaz. Redis yoksa/çökerse sessizce geç."""
    if not redis_client or not user:
        return
    try:
        s = user.streak_count or 0
        uid = str(user.id)
        redis_client.zadd(LB_ALLTIME_KEY, {uid: _lb_score(user.rank_points, s)})
        redis_client.zadd(LB_WEEKLY_KEY,  {uid: _lb_score(user.weekly_xp, s)})
    except Exception:
        pass  # Postgres kaynak; boot/rollover'daki lb_rebuild sürüklenmeyi düzeltir


def lb_rebuild():
    """Her iki sorted set'i Postgres'ten sıfırdan kur (boot + haftalık rollover sonrası)."""
    if not redis_client:
        return
    try:
        pipe = redis_client.pipeline()
        pipe.delete(LB_ALLTIME_KEY, LB_WEEKLY_KEY)
        for u in User.query.all():
            s = u.streak_count or 0
            uid = str(u.id)
            pipe.zadd(LB_ALLTIME_KEY, {uid: _lb_score(u.rank_points, s)})
            pipe.zadd(LB_WEEKLY_KEY,  {uid: _lb_score(u.weekly_xp, s)})
        pipe.execute()
    except Exception:
        pass


def _mark_lb_dirty(user_id):
    """Kullanıcıyı 'commit sonrası Redis sync gerekli' olarak işaretle. Eski davranış
    (award_xp içinde anında lb_sync_user) commit ÖNCESI yazıyordu; rollback olunca
    liderlik tablosu yukarı sürükleniyordu (H1-Redis). Artık sync after_commit'te."""
    if user_id is None:
        return
    db.session.info.setdefault("lb_dirty", set()).add(user_id)


@event.listens_for(db.session, "after_commit")
def _flush_lb_dirty(session):
    """Commit BAŞARILI olduktan sonra işaretli kullanıcıları Redis'e yaz (H1-Redis).
    Redis yoksa lb_sync_user zaten sessizce geçer."""
    dirty = session.info.pop("lb_dirty", None)
    if not dirty:
        return
    for uid in dirty:
        u = db.session.get(User, uid)
        if u:
            lb_sync_user(u)


@event.listens_for(db.session, "after_rollback")
@event.listens_for(db.session, "after_soft_rollback")
def _drop_lb_dirty(session, *args):
    """Rollback'te işaretleri at — XP kalıcı olmadı, Redis'e yazma."""
    session.info.pop("lb_dirty", None)


def award_xp(user_id, amount):
    user = db.session.get(User, user_id)
    if user:
        user.rank_points = (user.rank_points or 0) + amount
        user.weekly_xp = (user.weekly_xp or 0) + amount
        _mark_lb_dirty(user_id)  # Redis sync commit BAŞARILI olduktan sonra (after_commit)
        return user.rank_points
    return None


def get_level(xp):
    return 1 + (xp or 0) // 500


def get_title(level):
    if level <= 5:
        return "Fitness Yolcusu"
    elif level <= 10:
        return "Demir Bükücü"
    elif level <= 20:
        return "Kas Mimarı"
    elif level <= 50:
        return "FitX Efsanesi"
    else:
        return "Antrenman Tanrısı"


